function recolor(n, col, skip) {
  skip = skip || [];
  if (skip.indexOf(n.name)===-1) {
    if ('fills' in n && Array.isArray(n.fills) && n.fills.length) {
      n.fills = n.fills.map(f => (f.type==='SOLID') ? {type:'SOLID',visible:f.visible,opacity:f.opacity,blendMode:f.blendMode,color:col} : f);
    }
    if ('strokes' in n && Array.isArray(n.strokes) && n.strokes.length) {
      n.strokes = n.strokes.map(s => (s.type==='SOLID') ? {type:'SOLID',visible:s.visible,opacity:s.opacity,blendMode:s.blendMode,color:col} : s);
    }
  }
  if ('children' in n) n.children.forEach(c=>recolor(c,col,skip));
}
