  comp.resizeWithoutConstraints(414,80);
  comp.fills=solid(dark?C.bgDark:C.bgLight);
  const line=figma.createRectangle(); line.name='Divider'; line.resize(414,1);
  line.fills=solid(dark?C.dividerDark:C.dividerLight);
  comp.appendChild(line); line.x=0; line.y=0;
  const tabs=[['Main','Main'],['Payments','Payments'],['Cashback','Cashback'],['Invest','Invest'],['More','More']];
  const slot=366/5;
  tabs.forEach(function(pair,i){
    const label=pair[0], iconKey=pair[1];
    const isActive = label===active;
    const col = isActive ? C.accent : C.secDark;
    const tab=figma.createFrame(); tab.name='Tab / '+label; tab.fills=[]; tab.resize(slot,58);
    comp.appendChild(tab); tab.x=24+i*slot; tab.y=11;
    const ic=ICON[iconKey].createInstance(); recolor(ic,col);
    tab.appendChild(ic); ic.x=(slot-ic.width)/2; ic.y=3;
    const lb=mkText(label,10,'Medium',col);
    tab.appendChild(lb); lb.x=(slot-lb.width)/2; lb.y=33;
